import java.io.*;import java.nio.file.*;import java.util.*;
public class Practical42 {static void show(File f){System.out.printf("Name: %s%nPath: %s%nSize: %d%nReadable: %b, Writable: %b%nLast modified: %s%n",f.getName(),f.getAbsolutePath(),f.length(),f.canRead(),f.canWrite(),new Date(f.lastModified()));}public static void main(String[] a){try{if(a.length<2)throw new IllegalArgumentException("copy source destination | delete file | rename source destination");File f;switch(a[0]){case "copy":if(a.length!=3)throw new IllegalArgumentException();Files.copy(Path.of(a[1]),Path.of(a[2]),StandardCopyOption.REPLACE_EXISTING);f=new File(a[2]);break;case "delete":f=new File(a[1]);if(!f.delete())throw new IOException("Delete failed");System.out.println("Deleted: "+a[1]);return;case "rename":if(a.length!=3)throw new IllegalArgumentException();f=new File(a[1]);if(!f.renameTo(new File(a[2])))throw new IOException("Rename failed");f=new File(a[2]);break;default:throw new IllegalArgumentException("Unknown command");}show(f);}catch(Exception e){System.out.println("Error: "+e.getMessage());}}}
